// An overnight shortage and an operator rehearsal share the same runner.
proc rehearsal() {
    let attempts: int = 0;
    transaction {
        set attempts = attempts + 1;
        fulfill("practice", "gear", 1, "seal", 1, "east", "west");
        assert false;
    } recover (failure) {
        emit "rehearsal_reverted" { attempts: attempts; reason: code(failure); };
    }
}

proc main() {
    reserve("safety", "east", "gear", 3);
    rehearsal();
    fulfill("alpha", "gear", 6, "seal", 6, "east", "west");
    fulfill("beta", "gear", 5, "seal", 3, "west", "east");
    fulfill("gamma", "gear", 8, "seal", 8, "east", "west");
    release("safety", 3);
    fulfill("delta", "gear", 4, "seal", 2, "east", "west");
    emit "closing" {
        east_gear: available("east", "gear");
        west_gear: available("west", "gear");
    };
}

// Migration scaffold: retain this public signature.
proc fulfill(order: string, sku_a: string, qty_a: int,
             sku_b: string, qty_b: int, preferred: string, fallback: string) {
    emit "deferred" { order: order; reason: "NOT_MIGRATED"; };
}

import json
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest


class Smoke(unittest.TestCase):
    def test_transactional_reservation(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            (root / "input.json").write_text(
                '{"warehouses":{"east":{"gear":10},"west":{}}}')
            (root / "program.stock").write_text('''
proc main() {
    let attempted: int = 0;
    transaction {
        set attempted = 9;
        reserve("aborted", "east", "gear", 3);
        emit "not_committed" {};
        assert false;
    } recover (err) {
        emit "reverted" { attempted: attempted; reason: code(err); };
    }
    reserve("live", "east", "gear", 4);
    ship("live", 2);
    emit "free" { units: available("east", "gear"); };
}
''')
            process = subprocess.run(
                [sys.executable, "-m", "stockroom", str(root / "program.stock"),
                 "--inventory", str(root / "input.json"),
                 "--out", str(root / "out.json")], capture_output=True, text=True)
            self.assertEqual(process.returncode, 0, process.stderr)
            result = json.loads((root / "out.json").read_text())
            self.assertEqual(result["warehouses"]["east"]["gear"], 8)
            self.assertEqual(set(result["holds"]), {"live"})
            self.assertEqual(result["holds"]["live"]["remaining"], 2)
            self.assertEqual(result["events"], [
                {"id": 1, "name": "reverted", "data": {"attempted": 0, "reason": "ASSERT"}},
                {"id": 2, "name": "free", "data": {"units": 6}}])
            self.assertEqual(result["stats"], {"steps": 10, "committed": 0, "rolled_back": 1})


if __name__ == "__main__":
    unittest.main()

