    def _hold(self, hold_id, stmt):
        record = self.holds.get(hold_id)
        if record is None:
            raise self.domain("HOLD", "unknown hold %r" % hold_id, stmt)
        return record

    def exec_operation(self, stmt, scopes):
        args = [self.eval(expr, scopes) for expr in stmt.args]
        op = stmt.op
        if op == "receive":
            warehouse, sku, qty = args
            self._quantity(qty, stmt)
            self._name(sku, "SKU", stmt)
            stock = self._warehouse(warehouse, stmt)
            self.set_onhand(warehouse, sku, stock.get(sku, 0) + qty)
        elif op == "move":
            source, destination, sku, qty = args
            self._quantity(qty, stmt)
            self._name(sku, "SKU", stmt)
            src = self._warehouse(source, stmt)
            dst = self._warehouse(destination, stmt)
            if source == destination:
                raise self.domain("SAME_WAREHOUSE",
                                  "cannot move within warehouse %r" % source, stmt)
            if self._available(source, sku) < qty:
                raise self.domain("SHORTAGE", "insufficient free %r in %r"
                                  % (sku, source), stmt)
            self.set_onhand(source, sku, src.get(sku, 0) - qty)
            self.set_onhand(destination, sku, dst.get(sku, 0) + qty)
        elif op == "reserve":
            hold_id, warehouse, sku, qty = args
            self._quantity(qty, stmt)
            self._name(hold_id, "hold ID", stmt)
            self._name(sku, "SKU", stmt)
            self._warehouse(warehouse, stmt)
            if hold_id in self.holds:
                raise self.domain("DUPLICATE_HOLD", "hold %r already exists"
                                  % hold_id, stmt)
            if self._available(warehouse, sku) < qty:
                raise self.domain("SHORTAGE", "insufficient free %r in %r"
                                  % (sku, warehouse), stmt)
            self.set_hold(hold_id, (warehouse, sku, qty))
        else:  # release / ship
            hold_id, qty = args
            self._quantity(qty, stmt)
            self._name(hold_id, "hold ID", stmt)
            warehouse, sku, remaining = self._hold(hold_id, stmt)
            if qty > remaining:
                raise self.domain("SHORTAGE", "hold %r has only %d remaining"
                                  % (hold_id, remaining), stmt)
            self.set_hold(hold_id, (warehouse, sku, remaining - qty))
            if op == "ship":
                self.set_onhand(warehouse, sku,
                                self.warehouses[warehouse][sku] - qty)

    # ------------------------------------------------------------ expressions
    def eval(self, expr, scopes):
        kind = type(expr)
        if kind is ast.Literal:
            return expr.value
        if kind is ast.Var:
            name = expr.name
            for scope in reversed(scopes):
                if name in scope:
                    return scope[name]
            raise AssertionError("unresolved variable %r" % name)  # pragma: no cover
        if kind is ast.Binary:
            op = expr.op
            if op == "&&":
                return bool(self.eval(expr.left, scopes)) and bool(self.eval(expr.right, scopes))
            if op == "||":
                return bool(self.eval(expr.left, scopes)) or bool(self.eval(expr.right, scopes))
            left = self.eval(expr.left, scopes)
            right = self.eval(expr.right, scopes)
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if op in ("/", "%"):
                if right == 0:
                    raise self.fatal("division by zero", expr)
                quotient = _tdiv(left, right)
                return quotient if op == "/" else left - quotient * right
            if op == "==":
                return left == right
            if op == "!=":
                return left != right
            if op == "<":
                return left < right
            if op == "<=":
                return left <= right
            if op == ">":
                return left > right
            return left >= right
        if kind is ast.Unary:
            value = self.eval(expr.operand, scopes)
            return (not value) if expr.op == "!" else -value
        return self.eval_builtin(expr, scopes)

    def eval_builtin(self, expr, scopes):
        args = [self.eval(arg.expr, scopes) for arg in expr.args]
        name = expr.name
        if name == "len":
            return len(args[0])
        if name == "code":
            return args[0].error.code
        if name == "remaining":
            return self._hold(args[0], expr)[2]
        warehouse, sku = args
        stock = self._warehouse(warehouse, expr)
        if name == "onhand":
            return stock.get(sku, 0)
        return self._available(warehouse, sku)

"""Command-line driver: compile, load inventory, execute, publish atomically."""
import json
import os
import sys
import tempfile
import threading

from .checker import check_unit
from .errors import InputFailure, IOFailure, StockroomError, SyntaxFailure
from .interpreter import Interpreter
from .parser import parse_source

USAGE = ("usage: python -m stockroom PROGRAM --inventory INPUT --out OUTPUT "
         "[--library LIBRARY]")


def parse_args(argv):
    options = {"--inventory": None, "--out": None, "--library": None}
    program = None
    i = 0
    while i < len(argv):
        arg = argv[i]
        name, eq, inline = arg.partition("=")
        if name in options:
            if options[name] is not None:
                raise IOFailure("%s given more than once; %s" % (name, USAGE))
            if eq:
                value = inline
            else:
                i += 1
                if i >= len(argv):
                    raise IOFailure("%s requires a value; %s" % (name, USAGE))
                value = argv[i]
            options[name] = value
        elif arg.startswith("--") and arg != "--":
            raise IOFailure("unknown option %s; %s" % (arg, USAGE))
        elif program is None:
            program = argv[i + 1] if arg == "--" and i + 1 < len(argv) else arg
            if arg == "--":
                i += 1
        else:
            raise IOFailure("unexpected argument %r; %s" % (arg, USAGE))
        i += 1
    if program is None or options["--inventory"] is None or options["--out"] is None:
        raise IOFailure("missing required arguments; " + USAGE)
    return program, options["--inventory"], options["--out"], options["--library"]


def read_bytes(path):
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError as exc:
        raise IOFailure("cannot read %s: %s" % (path, exc.strerror or exc), path)


def decode_source(data, path):
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError as exc:
        prefix = data[:exc.start].decode("utf-8", "replace")
        line = prefix.count("\n") + 1
        column = len(prefix) - (prefix.rfind("\n") + 1) + 1
        raise SyntaxFailure("source is not valid UTF-8", path, line, column)


def _reject_duplicates(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise InputFailure("duplicate JSON key %r" % key)
        result[key] = value
    return result


class _NonInteger:
    pass


def _reject_constant(name):
    raise InputFailure("invalid JSON constant %s" % name)


def load_inventory(data, path):
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise InputFailure("inventory is not valid UTF-8", path)
    try:
        doc = json.loads(text, object_pairs_hook=_reject_duplicates,
                         parse_constant=_reject_constant,
                         parse_float=lambda _text: _NonInteger())
    except InputFailure as exc:
        exc.file = path
        raise
    except (ValueError, RecursionError) as exc:
        raise InputFailure("invalid JSON: %s" % exc, path)
    if not isinstance(doc, dict) or set(doc) != {"warehouses"}:
        raise InputFailure("inventory must be an object with exactly 'warehouses'", path)
    warehouses = doc["warehouses"]
    if not isinstance(warehouses, dict):
        raise InputFailure("'warehouses' must be an object", path)
    result = {}
    for name, stock in warehouses.items():
        if name == "":
            raise InputFailure("warehouse names must be nonempty", path)
        if not isinstance(stock, dict):
            raise InputFailure("warehouse %r must map SKUs to quantities" % name, path)
        entries = {}
        for sku, qty in stock.items():
            if sku == "":
                raise InputFailure("SKU names must be nonempty", path)
            if type(qty) is not int or qty < 0:
                raise InputFailure("quantity of %r in %r must be a nonnegative integer"
                                   % (sku, name), path)
            entries[sku] = qty
        result[name] = entries
    return result


def _same_file(a, b):
    try:
        return os.path.samefile(a, b)
    except OSError:
        return False


def publish(result, out_path, protected):
    try:
        text = json.dumps(result, ensure_ascii=False, indent=2) + "\n"
        payload = text.encode("utf-8")
    except UnicodeEncodeError:
        payload = (json.dumps(result, ensure_ascii=True, indent=2) + "\n").encode("ascii")
    except (TypeError, ValueError, RecursionError) as exc:
        raise IOFailure("cannot serialize result: %s" % exc, out_path)
    for other in protected:
        if other is not None and _same_file(out_path, other):
            raise IOFailure("output would overwrite an input file", out_path)
    parent = os.path.dirname(os.path.abspath(out_path))
    if not os.path.isdir(parent):
        raise IOFailure("output directory does not exist", out_path)
    if os.path.isdir(out_path):
        raise IOFailure("output path is a directory", out_path)
    tmp_path = None
    try:
        fd, tmp_path = tempfile.mkstemp(dir=parent, prefix="." + os.path.basename(out_path) + ".",
                                        suffix=".tmp")
        with os.fdopen(fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        if os.path.exists(out_path):
            try:
                os.chmod(tmp_path, os.stat(out_path).st_mode & 0o7777)
            except OSError:
                pass
        else:
            umask = os.umask(0)
            os.umask(umask)
            os.chmod(tmp_path, 0o666 & ~umask)
        os.replace(tmp_path, out_path)
        tmp_path = None
    except OSError as exc:
        raise IOFailure("cannot publish result: %s" % (exc.strerror or exc), out_path)
    finally:
        if tmp_path is not None:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


def execute(argv):
    program_path, inventory_path, out_path, library_path = parse_args(argv)
    library_bytes = read_bytes(library_path) if library_path is not None else None
    program_bytes = read_bytes(program_path)
    inventory_bytes = read_bytes(inventory_path)

    procs = []
    if library_bytes is not None:
        procs.extend(parse_source(decode_source(library_bytes, library_path), library_path))
    procs.extend(parse_source(decode_source(program_bytes, program_path), program_path))
    table = check_unit(procs, program_path)

    warehouses = load_inventory(inventory_bytes, inventory_path)
    interpreter = Interpreter(table, warehouses)
    interpreter.run()
    publish(interpreter.result(), out_path,
            (program_path, library_path, inventory_path))


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)
    outcome = {}

    def target():
        try:
            execute(argv)
            outcome["code"] = 0
        except StockroomError as exc:
            outcome["error"] = exc
        except RecursionError:
            outcome["error"] = SyntaxFailure("program nesting is too deep")
        except MemoryError:
            outcome["error"] = IOFailure("out of memory")

    sys.setrecursionlimit(200000)
    threading.stack_size(512 * 1024 * 1024)
    worker = threading.Thread(target=target)
    worker.start()
    worker.join()
    error = outcome.get("error")
    if error is None:
        return outcome.get("code", 1)
    sys.stderr.write(json.dumps(error.diagnostic()) + "\n")
    return error.exit_code

