// Bundle dispatch workflow (see /app/docs/fulfillment.md). Library only: no main.

// Ship both lines from preferred, else both from fallback, else defer.
// A shortage rolls the whole attempt back (holds, stock, events). Any other
// domain failure is replayed from the identical restored state, so it
// propagates with its original code, location and stack.
proc fulfill(order: string, sku_a: string, qty_a: int,
             sku_b: string, qty_b: int, preferred: string, fallback: string) {
    transaction {
        fulfill__attempt(order, sku_a, qty_a, sku_b, qty_b, preferred);
    } recover (first) {
        if (code(first) != "SHORTAGE") {
            fulfill__attempt(order, sku_a, qty_a, sku_b, qty_b, preferred);
            assert false;
        }
        transaction {
            fulfill__attempt(order, sku_a, qty_a, sku_b, qty_b, fallback);
        } recover (second) {
            if (code(second) != "SHORTAGE") {
                fulfill__attempt(order, sku_a, qty_a, sku_b, qty_b, fallback);
                assert false;
            }
            emit "deferred" { order: order; reason: "SHORTAGE"; };
        }
    }
}

// One all-or-nothing attempt from a single warehouse. Holds are reserved for
// both lines before either ships, so a shared SKU is counted against one pool.
proc fulfill__attempt(order: string, sku_a: string, qty_a: int,
                      sku_b: string, qty_b: int, warehouse: string) {
    let hold_a: string = order + ".a";
    let hold_b: string = order + ".b";
    reserve(hold_a, warehouse, sku_a, qty_a);
    reserve(hold_b, warehouse, sku_b, qty_b);
    ship(hold_a, qty_a);
    ship(hold_b, qty_b);
    emit "fulfilled" { order: order; warehouse: warehouse; units: qty_a + qty_b; };
}
