"""Diagnostics and control-transfer signals."""

EXIT_CODES = {
    "SYNTAX": 2,
    "STATIC": 3,
    "DOMAIN": 4,
    "RUNTIME": 5,
    "INPUT": 6,
    "IO": 7,
}


class StockroomError(Exception):
    """A failure that terminates the run with a JSON diagnostic."""

    category = "IO"

    def __init__(self, message, file=None, line=None, column=None):
        super().__init__(message)
        self.message = message or self.category.lower() + " error"
        self.file = file
        self.line = line
        self.column = column

    def diagnostic(self):
        out = {"error": self.category, "message": self.message}
        if self.file is not None:
            out["file"] = self.file
        if self.line is not None:
            out["line"] = self.line
            out["column"] = self.column
        return out

    @property
    def exit_code(self):
        return EXIT_CODES[self.category]


class SyntaxFailure(StockroomError):
    category = "SYNTAX"


class StaticFailure(StockroomError):
    category = "STATIC"


class InputFailure(StockroomError):
    category = "INPUT"


class IOFailure(StockroomError):
    category = "IO"


class RuntimeFatal(StockroomError):
    """Fatal RUNTIME error: never caught by `recover`."""

    category = "RUNTIME"

    def __init__(self, message, file, line, column, stack):
        super().__init__(message, file, line, column)
        self.stack = list(stack)

    def diagnostic(self):
        out = super().diagnostic()
        out["stack"] = self.stack
        return out


class DomainError(StockroomError):
    """Recoverable inventory/assert failure."""

    category = "DOMAIN"

    def __init__(self, code, message, file, line, column, stack):
        super().__init__(message, file, line, column)
        self.code = code
        self.stack = list(stack)

    def diagnostic(self):
        out = super().diagnostic()
        out["code"] = self.code
        out["stack"] = self.stack
        return out


class ControlSignal(Exception):
    """Successful nonlocal control transfer (never a recoverable error)."""


class BreakSignal(ControlSignal):
    pass


class ContinueSignal(ControlSignal):
    pass


class ReturnSignal(ControlSignal):
    pass

