    def test_error_in_recovery_goes_outward(self):
        res = self.ok('''proc main() {
  transaction {
    transaction { assert false; } recover (e) { emit "inner" {}; receive("nowhere", "x", 1); }
  } recover (o) { emit "outer" { c: code(o); }; }
}''')
        self.assertEqual(self.events(res), [("outer", {"c": "WAREHOUSE"})])
        self.assertEqual(res["stats"], {"steps": 6, "committed": 0, "rolled_back": 2})

    def test_nested_commit_then_outer_rollback(self):
        res = self.ok('''proc main() {
  let v: int = 0;
  transaction {
    transaction { set v = 1; emit "in" {}; reserve("h", "east", "gear", 2); } 
    transaction { assert false; } recover (e) { set v = v + 10; emit "rec" { v: v; }; }
    receive("east", "newsku", 5);
    assert v == 0;
  } recover (e) { emit "after" { v: v; c: code(e); onhand: onhand("east", "newsku"); }; }
}''')
        self.assertEqual(self.events(res), [("after", {"v": 0, "c": "ASSERT", "onhand": 0})])
        self.assertEqual(res["holds"], {})
        self.assertEqual(res["warehouses"], INV["warehouses"])
        self.assertEqual(res["stats"]["committed"], 1)
        self.assertEqual(res["stats"]["rolled_back"], 2)

    def test_control_transfer_commits(self):
        res = self.ok('''
proc f() {
  transaction { emit "f" {}; transaction { return; } }
  emit "unreached" {};
}
proc main() {
  let i: int = 0;
  while (true) {
    set i = i + 1;
    transaction {
      emit "loop" { i: i; };
      if (i < 3) { transaction { continue; } }
      break;
    }
  }
  transaction { f(); emit "after_f" {}; assert false; } recover (e) { emit "r" {}; }
  f();
}''')
        self.assertEqual([e["name"] for e in res["events"]], ["loop", "loop", "loop", "r", "f"])
        self.assertEqual([e["id"] for e in res["events"]], [1, 2, 3, 4, 5])
        # loop: 3 outer + 2 inner continue; first f: 2 (rolled back later); second f: 2
        self.assertEqual(res["stats"]["committed"], 9)
        self.assertEqual(res["stats"]["rolled_back"], 1)

    def test_return_does_not_commit_caller(self):
        res = self.ok('''
proc f() { return; }
proc main() { transaction { f(); emit "x" {}; assert false; } recover (e) { emit "y" {}; } }''')
        self.assertEqual(self.events(res), [("y", {})])
        self.assertEqual(res["stats"], {"steps": 6, "committed": 0, "rolled_back": 1})

