 proc f() { return; }
 proc main() { transaction { f(); emit "x" {}; assert false; } recover (e) { emit "y" {}; } }''')
         self.assertEqual(self.events(res), [("y", {})])
         self.assertEqual(res["stats"], {"steps": 6, "committed": 0, "rolled_back": 1})

     def test_operations(self):
