   move("east", "west", "gear", 4);
   reserve("h", "east", "gear", 6);
   emit "a" { avail: available("east", "gear"); on: onhand("east", "gear"); r: remaining("h"); m: onhand("west", "missing"); };
   release("h", 2);
   ship("h", 4);
   receive("west", "bolt", 3);
   move("west", "east", "bolt", 3);
   reserve("closed", "west", "gear", 4);
   ship("closed", 4);
 }''', inventory=inv)
         self.assertEqual(res["warehouses"], {"east": {"gear": 2, "zero": 0, "bolt": 3}, "west": {"gear": 0, "bolt": 0}})
         self.assertEqual(res["holds"]["h"], {"warehouse": "east", "sku": "gear", "remaining": 0})
         self.assertEqual(res["holds"]["closed"]["remaining"], 0)
         self.assertEqual(self.events(res)[0][1], {"avail": 0, "on": 6, "r": 6, "m": 0})

     def test_domain_codes(self):
         cases = [
             ('receive("east", "gear", 0);', "QUANTITY"), ('receive("east", "gear", -1);', "QUANTITY"),
             ('receive("east", "", 1);', "NAME"), ('reserve("", "east", "gear", 1);', "NAME"),
             ('receive("north", "gear", 1);', "WAREHOUSE"), ('move("east", "east", "gear", 1);', "SAME_WAREHOUSE"),
             ('move("east", "north", "gear", 1);', "WAREHOUSE"), ('move("east", "west", "gear", 11);', "SHORTAGE"),
             ('reserve("h", "east", "gear", 11);', "SHORTAGE"),
             ('reserve("h", "east", "gear", 1); ship("h", 1); reserve("h", "east", "gear", 1);', "DUPLICATE_HOLD"),
             ('reserve("h", "east", "gear", 1); release("h", 2);', "SHORTAGE"),
             ('release("h", 1);', "HOLD"), ('ship("h", 1);', "HOLD"),
             ('let x: int = remaining("h");', "HOLD"), ('let x: int = onhand("north", "a");', "WAREHOUSE"),
             ('reserve("h", "east", "gear", 8); move("east", "west", "gear", 3);', "SHORTAGE"),
             ("assert false;", "ASSERT"),
         ]
         for body, code in cases:
             with self.subTest(body):
                 res = self.ok('proc main() { transaction { %s } recover (e) { emit "c" { c: code(e); }; } }' % body)
                 self.assertEqual(self.events(res), [("c", {"c": code})])
                 self.assertEqual(res["warehouses"], INV["warehouses"])
                 self.assertEqual(res["holds"], {})
                 d = self.fails("proc main() { %s }" % body, 4)
                 self.assertEqual(d["code"], code)

     def test_stats_counts(self):
         res = self.ok('''proc g(n: int) { if (n > 0) { emit "g" {}; } else { return; } }
 proc main() { let i: int = 0; while (i < 2) { set i = i + 1; g(i); } g(0); }''')
         # let, while, [set, call, if, emit] x2, call, if, return = 2 + 8 + 3
         self.assertEqual(res["stats"]["steps"], 13)


 class Workflow(Base):
     def test_unknown_warehouse_not_swallowed(self):
         d = self.fails('proc main() { fulfill("o", "gear", 1, "gear", 1, "nowhere", "east"); }', 4, library=WORKFLOW)
         self.assertEqual(d["code"], "WAREHOUSE")
         d = self.fails('proc main() { reserve("o.b", "east", "gear", 1); fulfill("o", "gear", 1, "gear", 1, "east", "west"); }', 4, library=WORKFLOW)
         self.assertEqual(d["code"], "DUPLICATE_HOLD")

     def test_same_sku_and_fallback(self):
         inv = {"warehouses": {"a": {"x": 5}, "b": {"x": 6, "y": 1}}}
         res = self.ok('''proc main() {
   let order: string = "mine"; let qty_a: int = 77;
   fulfill("o1", "x", 3, "x", 3, "a", "b");
   fulfill("o2", "x", 3, "x", 3, "a", "b");
   fulfill(order = "o3", sku_a = "x", qty_a = 2, sku_b = "x", qty_b = 2, preferred = "a", fallback = "b");
