 }''', inventory=inv, library=WORKFLOW)
         self.assertEqual([e["name"] for e in res["events"]], ["r", "deferred", "fulfilled"])
         self.assertEqual(res["warehouses"]["a"], {"x": 3})


 class InputAndIO(Base):
     def test_bad_inputs(self):
         for raw in ['{"warehouses":{"e":{"g":true}}}', '{"warehouses":{"e":{"g":-1}}}',
                     '{"warehouses":{"e":{"g":1.0}}}', '{"warehouses":{},"x":1}', '{}', '[]',
