                                 str(d / "i.json"), "--out", str(d / "o.json")],
                                capture_output=True, text=True, cwd=str(APP))
             self.assertEqual(p.returncode, 0)
             self.assertEqual(sorted(x.name for x in d.iterdir()), ["i.json", "o.json", "p.stock"])


